(() => {
 'use strict';
 // Small independent mechanics calculations; neither solver decks nor Nastran results.
 const ui=window.BeamLabs.ui,G=window.BeamLabs.graphics,A=window.LessonArticle;
 const fmt=(x,n=4)=>Number.isFinite(x)?Number((Math.abs(x)<1e-12?0:x).toPrecision(n)).toLocaleString('en-US',{maximumFractionDigits:6}):'—';
 const dot=(a,b)=>a.reduce((s,x,i)=>s+x*b[i],0);
 function rank(M,tol=1e-10){if(!M.length)return 0;const a=M.map(r=>r.slice());let k=0;for(let j=0;j<a[0].length&&k<a.length;j++){let p=k;for(let i=k+1;i<a.length;i++)if(Math.abs(a[i][j])>Math.abs(a[p][j]))p=i;if(Math.abs(a[p][j])<tol)continue;[a[k],a[p]]=[a[p],a[k]];const d=a[k][j];a[k]=a[k].map(x=>x/d);for(let i=k+1;i<a.length;i++){const c=a[i][j];a[i]=a[i].map((x,l)=>x-c*a[k][l]);}k++;}return k;}
 const rigidRows=([x,y,z])=>[[1,0,0,0,z,-y],[0,1,0,-z,0,x],[0,0,1,y,-x,0]];
 const supportSets={
  stable:[{p:[0,0,0],c:[0,1,2],name:'A'},{p:[1,0,0],c:[1,2],name:'B'},{p:[0,1,0],c:[2],name:'C'}],
  collinear:[{p:[0,0,0],c:[0,1,2],name:'A'},{p:[1,0,0],c:[1,2],name:'B'},{p:[2,0,0],c:[2],name:'C'}],
  point:[{p:[0,0,0],c:[0,1,2],name:'A'}],
  face:[{p:[0,0,0],c:[0],name:'A'},{p:[0,1,0],c:[0],name:'B'},{p:[0,0,1],c:[0],name:'C'},{p:[0,1,1],c:[0],name:'D'}]
 };
 const equations={valid:{C:[[1,-1,0],[0,1,-1]],d:[0,0]},redundant:{C:[[1,-1,0],[0,1,-1],[1,0,-1]],d:[0,0,0]},inconsistent:{C:[[1,-1,0],[0,1,-1],[1,0,-1]],d:[0,0,1]},fixed:{C:[[1,-1,0],[0,1,-1],[1,0,0]],d:[0,0,0]}};
 const core={rank,rigidRows,supportSets,equations,
  supportRank:key=>rank(supportSets[key].flatMap(({p,c})=>c.map(i=>rigidRows(p)[i]))),
  beam:(kind,x)=>{const P=100,L=400,EI=210000*10000,a=L/2,t=Math.min(x,L-x);let w;if(kind==='simple')w=P*t*(3*L*L-4*t*t)/(48*EI);else if(kind==='fixed')w=P*t*t*(3*L-4*t)/(48*EI);else w=x<=a?P*x*x*(3*a-x)/(6*EI):P*a*a*(3*x-a)/(6*EI);return {w,RA:kind==='cantilever'?P:P/2,RB:kind==='cantilever'?0:P/2,MA:kind==='cantilever'?P*a:kind==='fixed'?P*L/8:0,MB:kind==='fixed'?-P*L/8:0};},
  inclined:(angle,wrong=false)=>{const a=angle*Math.PI/180,n=wrong?[0,1]:[Math.cos(a),Math.sin(a)],F=[100,0],R=n.map(x=>-x*dot(n,F)),u=F.map((x,i)=>(x+R[i])/100);return {n,R,u,normal:dot([Math.cos(a),Math.sin(a)],u)};},
  imposed:(d,P=0)=>{const k1=100,k2=300,u=(P+k2*d)/(k1+k2),N1=k1*u,N2=k2*(d-u);return {u,N1,N2,RA:-N1,RB:N2,U:(k1*u*u+k2*(d-u)**2)/2};},
  ratio:(r,P=120,y=0)=>{const kA=100,kB=200,uB=(P-r*kA*y)/(kB+r*r*kA),uA=r*uB+y,QA=kA*uA,QB=kB*uB-P;return {uA,uB,QA,QB,k:kB+r*r*kA,U:(kA*uA*uA+kB*uB*uB)/2};},
  conflict:key=>{const {C,d}=equations[key],r=rank(C),aug=rank(C.map((row,i)=>[...row,d[i]]));return {r,aug,free:3-r,redundant:C.length-r,inconsistent:aug>r};},
  compliance:r=>({u:.1*(1+1/r),support:.1/r,structure:.1,error:1/r}),
  weak:(angle,log)=>{const a=angle*Math.PI/180,c=Math.cos(a),s=Math.sin(a),strong=1000,weak=strong*10**log;return {K:[[strong*c*c+weak*s*s,(strong-weak)*s*c],[(strong-weak)*s*c,strong*s*s+weak*c*c]],ratio:weak/strong,strong,weak,n:[-s,c]};},
  reactions:(a,P=120,L=400)=>({RA:P*(L-a)/L,RB:P*a/L,MA:0,MB:0}),
  symmetry:(axis,anti=false)=>{const normal=axis,t=[0,1,2].filter(i=>i!==axis);return (anti?[...t,normal+3]:[normal,...t.map(i=>i+3)]).sort((a,b)=>a-b).map(i=>i+1);}
 };
 const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const text=(x,y,s,a='middle')=>`<text x="${x}" y="${y}" text-anchor="${a}">${esc(s)}</text>`;
 const line=(a,b,c='el-edge')=>`<line x1="${a[0]}" y1="${a[1]}" x2="${b[0]}" y2="${b[1]}" class="${c}"/>`;
 const path=(ps,c='el-edge')=>`<polyline points="${ps.map(p=>p.join(',')).join(' ')}" class="${c}"/>`;
 const node=(x,y)=>`<circle cx="${x}" cy="${y}" r="4" class="el-node"/>`;
 function arrow(a,b,c='el-force'){const dx=b[0]-a[0],dy=b[1]-a[1],l=Math.hypot(dx,dy);if(l<.01)return '';const u=dx/l,v=dy/l,h=Math.min(8,l/2);return line(a,b,c)+`<polygon points="${b} ${b[0]-h*u+3*v},${b[1]-h*v-3*u} ${b[0]-h*u-3*v},${b[1]-h*v+3*u}" class="${c}-head"/>`;}
 const wall=(x,y)=>line([x,y-30],[x,y+30])+[-2,-1,0,1,2].map(i=>line([x,y+i*12],[x-9,y+i*12+8])).join('');
 const roller=(x,y,pin=false)=>`<path d="M${x} ${y}l-11 18h22Z" class="el-soft"/>`+(pin?'':[-6,6].map(d=>`<circle cx="${x+d}" cy="${y+22}" r="3" class="el-edge"/>`).join(''))+line([x-18,y+(pin?20:28)],[x+18,y+(pin?20:28)]);
 function spring(a,b){const dx=b[0]-a[0],dy=b[1]-a[1],l=Math.hypot(dx,dy);return path([a,...Array.from({length:13},(_,i)=>{const t=.15+.7*i/12,d=i===0||i===12?0:i%2?6:-6;return[a[0]+t*dx-d*dy/l,a[1]+t*dy+d*dx/l];}),b]);}
 const svg=(body,label,h=230)=>`<svg class="theory-lab-svg" viewBox="0 0 360 ${h}" role="img" aria-label="${esc(label)}">${body}</svg>`;
 const frame=(c,caption)=>ui.box('',c,caption),table=(h,r)=>A.table(h,r,{narrow:true});
 const out=(e,v)=>Object.entries(v).forEach(([k,x])=>{if(e.out[k])e.out[k].textContent=fmt(+x);});
 function symmetryFigure(){return '<figure class="element-figure">'+svg(`<rect x="170" y="35" width="20" height="150" class="el-soft"/>${line([180,25],[180,196],'el-ghost')}${line([45,118],[315,118])}${node(90,118)}${node(270,118)}${arrow([90,110],[90,65],'el-motion')}${arrow([270,110],[270,65],'el-motion')}${arrow([95,143],[130,143])}${arrow([265,143],[230,143])}${text(180,18,'x = 0')}${text(90,52,'uy')}${text(270,52,'uy')}${text(120,164,'ux')}${text(240,164,'−ux')}${text(180,216,'ux(0) = 0,  θy(0) = θz(0) = 0')}`,'x=0の鏡面に対する対称変形：接線変位は同方向、法線変位は逆方向',235)+'<figcaption>対称条件の模式図。接線方向の変位は鏡面の両側で同方向、法線方向は逆方向です。鏡面上では法線変位が0になります。図は対応するベクトルを示し、変形量の実測値ではありません。回転自由度がある場合、鏡面内の軸まわりの回転も0にします。</figcaption></figure>';}
 function interfaceFigure(){return '<figure class="element-figure">'+svg(`<rect x="233" y="38" width="62" height="145" class="el-soft"/>${line([35,110],[95,110],'b3-edge')}${line([95,110],[240,65],'el-ghost')}${line([95,110],[240,155],'el-ghost')}${node(95,110)}${node(240,65)}${node(240,155)}${arrow([240,65],[309,65])}${arrow([240,155],[171,155])}${text(300,48,'+F')}${text(177,178,'−F')}${text(77,86,'My')}${line([327,65],[327,155])}${line([322,65],[332,65])}${line([322,155],[332,155])}${text(342,113,'h')}${arrow([40,203],[83,203],'el-axis')}${arrow([40,203],[40,162],'el-axis')}${text(94,207,'x')}${text(28,159,'z')}${text(216,213,'ΣFx = 0,  My = Fh')}`,'梁の曲げモーメントをソリッド面上の力の組へ受け渡す',235)+'<figcaption>梁端のMyを、上下にh離れたソリッド面上の逆向きの力±Fで受け渡す模式図です。合力は0でもモーメントFhが残ります。実際の結合では面上の複数節点に分布させ、支持面の変形をどこまで許すかも選びます。</figcaption></figure>';}
 function overhangFigure(){
  const beam=line([46,76],[310,76]), blocks=roller(46,77,true)+roller(244,77,true);
  const assumed=blocks+beam+arrow([310,36],[310,72])+text(310,27,'100 N')
   +arrow([46,37],[46,72],'el-motion')+text(46,27,'33 N')
   +arrow([244,139],[244,106],'el-motion')+text(244,157,'133 N')
   +text(46,119,'A')+text(213,103,'B');
  const lift=roller(46,205,true)+roller(244,205,true)+line([46,205],[310,205],'el-ghost')
   +line([46,175],[310,215])+arrow([310,177],[310,209])+text(46,164,'A')+text(243,191,'B');
  return '<figure class="element-figure">'+svg(assumed+lift,'上は両支点が接していると仮定した力。下は板が右支点を中心に傾き、左の台との間に隙間が開く様子。',241)
   +'<figcaption>上図のAの下向き矢印は、接触を保つために必要な力です。下図のように載せただけなら、A側が浮きます。破線は元の板の位置。傾きは模式的に拡大しています。</figcaption></figure>';
 }
 const labs={
  supports:{html:()=>frame(ui.select('kind','同じ梁の支持',[['simple','左ピン・右ローラー'],['fixed','両端固定'],['cantilever','左固定・右自由']],'simple'),'L=400 mm、E=210,000 MPa、I=10,000 mm⁴。中央に100 N。Euler–Bernoulli梁、小変形。破線は変形前、実線は全ケース共通の200倍。固定端の曲げ反力は数値欄に示します。'),draw(e,v){const r=core.beam(v.kind,200),end=core.beam(v.kind,400),points=Array.from({length:81},(_,i)=>[55+250*i/80,85+200*core.beam(v.kind,i*5).w]);e.plot.innerHTML=svg(line([55,85],[305,85],'el-ghost')+path(points,'b3-edge')+(v.kind==='simple'?roller(55,85,true)+roller(305,85):wall(55,85)+(v.kind==='fixed'?wall(305,85):''))+arrow([180,28],[180,75])+text(180,18,'P = 100 N')+text(55,135,'A')+text(305,135,'B')+text(180,214,'L = 400 mm'),'支持だけを変えた梁の変形',235)+table(['量','値'],[['中央の下向き変位 (mm)',fmt(r.w)],['右端の下向き変位 (mm)',fmt(end.w)],['上向き反力 RA / RB (N)',fmt(r.RA)+' / '+fmt(r.RB)],['反時計回り MA / MB (N·mm)',fmt(r.MA)+' / '+fmt(r.MB)]]);e.readout.innerHTML=v.kind==='simple'?'<strong>端の変位は0でも、端の傾きは0ではありません。</strong>両端固定へ変えると、同じ中央荷重でも中央変位は1/4になります。':v.kind==='fixed'?'<strong>回転を止めた分だけ曲げ反力が生じます。</strong>反力合計が100 Nで合うことだけでは、正しい支持を選んだ証明になりません。':'荷重は自由端ではなく中央です。荷重点より右にも回転による変位が生じます。右端に支持を追加すると別の構造になります。';}},
  rigid:{html:()=>frame(ui.select('set','支持する点と方向',[['stable','3点・3–2–1（非一直線）'],['collinear','3点・3–2–1（一直線）'],['point','1点の並進123だけ'],['face','片面の法線1だけ']],'stable'),'連続した1個の3次元物体の剛体運動だけを調べます。点間長さは正規化。矢印は止める並進方向であり、荷重ではありません。要素内部の機構は別に点検します。'),draw(e,v){const set=supportSets[v.set],r=core.supportRank(v.set),verts=[[0,0,0],[2,0,0],[2,1,0],[0,1,0],[0,0,1],[2,0,1],[2,1,1],[0,1,1]],edges=[[0,1],[1,2],[2,3],[3,0],[4,5],[5,6],[6,7],[7,4],[0,4],[1,5],[2,6],[3,7]],items=edges.map(([a,b])=>({k:'line',p:[verts[a],verts[b]],c:'b3-ghost'}));for(const {p,c,name}of set){items.push({k:'dot',p:[p],c:'b3-node',r:3.5},{k:'text',p:[p],s:name,dy:-12});c.forEach(i=>{const end=p.slice();end[i]-=.36;items.push({k:'arrow',p:[end,p],c:'el-motion'});});}for(let i=0;i<3;i++){const a=[2.5,.1,0],b=a.slice();b[i]+=.4;items.push({k:'arrow',p:[a,b],c:'b3-axis'},{k:'text',p:[b],s:['x','y','z'][i],dy:-7});}e.plot.innerHTML=G.render3d(items,{cam:G.camera(-48,25),h:240,pad:35,label:'支持点の配置と止める方向'})+table(['点','位置 (x,y,z)','止める成分'],set.map(s=>[s.name,s.p.join(', '),s.c.map(i=>i+1).join('')]))+table(['拘束の本数','独立な拘束数','残る剛体運動'],[[set.reduce((s,x)=>s+x.c.length,0),r,6-r]]);e.readout.innerHTML=v.set==='stable'?'<strong>独立な6条件なので剛体運動は残りません。</strong>ただし3–2–1は支持条件そのものです。どの実物にも無条件に置いてよいという意味ではありません。':v.set==='collinear'?'<strong>6個止めても、独立なのは5条件。</strong>A–B–Cを通るx軸まわりの回転が残ります。拘束数だけを数えず、位置と方向を確かめます。':v.set==='point'?'<strong>1点の並進を止めても、その点まわりの3回転が残ります。</strong>ソリッドの点に456を足すことでは、この剛体回転を止められません。':'法線xの条件はTx・Ry・Rzを止めます。面内のTy・Tzと、面の法線まわりのRxは残ります。';}},
  inclined:{html:()=>frame(ui.slider('angle','止めたい法線 n の角度（°）',0,90,5,30)+ui.select('wrong','入力した拘束',[['correct','局所1軸をnに合わせ、成分1を止める'],['wrong','取り違えて全体yの成分を止める']],'correct'),'節点をx・yの各方向でk=100 N/mmのばねが地面へ支え、さらに滑りガイドを付けます。F=(100,0) N。灰色の破線はガイドの接線、青い矢印nは法線、緑の破線矢印uは変位を80倍。赤いF・Rは同じ縮尺です。'),draw(e,v){out(e,v);const a=+v.angle*Math.PI/180,n=[Math.cos(a),Math.sin(a)],t=[-n[1],n[0]],r=core.inclined(+v.angle,v.wrong==='wrong'),o=[170,125],map=(w,s=80)=>[o[0]+s*w[0],o[1]-s*w[1]];e.plot.innerHTML=svg(line(map(t,-85),map(t,85),'el-ghost')+node(...o)+arrow(o,map(n,60),'el-axis')+text(...map(n,75),'n')+arrow(o,map([100,0],.6))+text(245,118,'F')+arrow(o,map(r.R,.6))+(Math.hypot(...r.R)>1e-8?text(map(r.R,.6)[0]-12,map(r.R,.6)[1]+12,'R'):'')+arrow(o,map(r.u),'el-motion')+(Math.hypot(...r.u)>1e-8?text(map(r.u)[0]+15,map(r.u)[1]+14,'u'):'')+text(75,215,'K = kI'),'斜めのガイドの法線と許される移動',240)+table(['量','x','y'],[['変位 u (mm)',...r.u.map(x=>fmt(x))],['ガイド反力 R (N)',...r.R.map(x=>fmt(x))]]);e.readout.innerHTML=`意図した法線変位 n·u = <strong>${fmt(r.normal)} mm</strong>。${v.wrong==='wrong'?'全体yを止めると、想定したガイドから外れる方向へ動きます。CPで位置を入力しただけでは、SPCの方向は変わりません。':'法線変位は0、接線方向はばねの変形を伴って動けます。反力は法線に沿い、変位とは直交します。'}`;}},
  imposed:{html:()=>frame(ui.slider('d','右端Bの指定変位 d（mm）',-.5,.5,.05,.2)+ui.select('P','中間点Cに加える力 P（N）',[[0,'0'],[40,'+40']],0),'A–C–Bを2本の軸ばねで結び、Aは0、Bは指定変位d。k1=100、k2=300 N/mm。Cの変位は未知です。右を正、破線は変形前、変位表示は80倍。'),draw(e,v){out(e,v);const r=core.imposed(+v.d,+v.P),x=[45,175+80*r.u,305+80*(+v.d)];e.plot.innerHTML=svg(wall(45,110)+spring([x[0],110],[x[1],110])+spring([x[1],110],[x[2],110])+[45,175,305].map(a=>line([a,80],[a,145],'el-ghost')).join('')+x.map(a=>node(a,110)).join('')+text(45,160,'A: uA = 0')+text(175,160,'C: uC = ?')+text(300,185,'B: uB = d')+text(110,75,'k1')+text(245,75,'k2')+arrow([x[2],110],[x[2]+30*Math.sign(+v.d),110],'el-motion')+(+v.P?arrow([x[1],100],[x[1]+40,100])+text(190,40,'P = 40 N'):'') ,'指定変位から求まる未知変位と支持反力',215)+table(['量','値'],[['uC (mm)',fmt(r.u)],['Aの反力 RA (N)',fmt(r.RA)],['Bの反力 RB (N)',fmt(r.RB)],['RA + RB + P (N)',fmt(r.RA+r.RB+(+v.P))],['ひずみエネルギー U (N·mm)',fmt(r.U)]]);e.readout.innerHTML='<strong>指定変位dを与えると、Bの反力が未知になります。</strong>Cの力Pもある場合、2本のばねの軸力は同じとは限りません。Pと反力を同じ正方向で足して検算します。';}},
  mpc:{html:()=>frame(ui.slider('r','変位比 r：uA = r uB + y',-2,2,.25,2)+ui.select('y','右辺 y（mm）',[[0,'0：同次MPC'],[.2,'+0.2：非同次拘束']],0),'節点A・Bは別々に地面へ軸ばねでつながり、kA=100、kB=200 N/mm。Bへ+120 N。Aの成分を従属、Bの成分を独立とする理想拘束です。図は独自の1方向の関係で、RBE3全体を代用した式ではありません。変位表示は80倍。'),draw(e,v){out(e,v);const r=core.ratio(+v.r,120,+v.y),a=130+80*r.uA,b=130+80*r.uB;e.plot.innerHTML=svg(wall(40,80)+wall(40,170)+spring([40,80],[a,80])+spring([40,170],[b,170])+line([130,50],[130,195],'el-ghost')+node(a,80)+node(b,170)+arrow([b,170],[b+45,170])+text(70,50,'kA')+text(70,140,'kB')+text(a,63,'A')+text(b,205,'B')+text(b+35,150,'P = 120 N')+text(245,25,'uA = r uB + y'),'独立成分と従属成分の動き・力',230)+table(['量','値'],[['uA / uB (mm)',fmt(r.uA)+' / '+fmt(r.uB)],['Aへの拘束力 QA (N)',fmt(r.QA)],['Bへの拘束力 QB (N)',fmt(r.QB)],['仮想仕事の係数 r QA + QB (N)',fmt((+v.r)*r.QA+r.QB)],['縮約剛性 kB + r²kA (N/mm)',fmt(r.k)]]);e.readout.innerHTML='<strong>独立成分は、値を先に指定する成分という意味ではありません。</strong>Bの変位も全体のつり合いで求まります。力は変位比の逆方向へ仕事が一致するように伝わります。';}},
  conflict:{html:()=>frame(ui.select('case','同時に課す条件',[['valid','A=B、B=C'],['redundant','さらにA=C（重複）'],['inconsistent','さらにA−C=1 mm（矛盾）'],['fixed','さらにA=0（地面へ固定）']],'valid'),'3つの1方向変位に対する拘束式だけを検査します。独立な式の数と、指定値を含めた矛盾の有無を比べます。通常のNastran MPCでの先頭従属成分の重複検査は、これに加えて必要です。'),draw(e,v){const r=core.conflict(v.case);e.plot.innerHTML=svg(line([65,105],[180,105])+line([180,105],[295,105])+[65,180,295].map((x,i)=>node(x,105)+text(x,82,['A','B','C'][i])).join('')+text(120,135,'uA − uB = 0')+text(245,165,'uB − uC = 0')+(v.case==='valid'?'':v.case==='fixed'?wall(65,105)+text(180,205,'uA = 0'):path([[65,100],[65,40],[295,40],[295,100]],'el-motion')+text(180,25,v.case==='inconsistent'?'uA − uC = 1 mm':'uA − uC = 0')),'拘束関係の閉じた経路と重複',235)+table(['量','値'],[['式の本数',equations[v.case].C.length],['係数行列の階数 rank C',r.r],['拡大行列の階数 rank [C|d]',r.aug],['残る自由度（整合する場合）',r.inconsistent?'—':r.free]]);e.readout.innerHTML=r.inconsistent?'<strong>同時に満たす変位は存在しません。</strong>前の2式からA=Cなのに、追加の式は1 mm離せと要求しています。':r.redundant?'<strong>3本目は新しい条件を増やしていません。</strong>従属成分を変えるだけでは、この代数的な重複は消えません。':v.case==='valid'?'<strong>3点が一緒に動く自由度が1つ残ります。</strong>部材間をつないだことと、地面に支えたことは別です。':'A=0は新しい独立条件なので、A=B=C=0となります。実物が許す共通移動を止めてよいかも判断します。';}},
  compliance:{html:()=>frame(ui.slider('log','支持剛性比 ks / kb の10の指数',-1,6,1,1),'先端力100 N、部材の軸剛性kb=1,000 N/mm。支持ばねksと部材は直列です。理想固定との変位差と、支持へ蓄えるエネルギーを評価します。破線は変形前、変位表示は50倍。'),draw(e,v){out(e,v);const ratio=10**(+v.log),r=core.compliance(ratio),s=70+50*r.support,b=210+50*r.u;e.plot.innerHTML=svg(wall(30,100)+spring([30,100],[s,100])+line([s,100],[b,100],'b3-edge')+node(s,100)+node(b,100)+arrow([b,100],[b+35,100])+line([70,65],[70,145],'el-ghost')+line([210,65],[210,145],'el-ghost')+text(48,50,'ks')+text(155,78,'kb = 1,000')+text(280,50,'P = 100 N')+text(180,190,'ks / kb = '+fmt(ratio)),'支持の柔らかさが全変位へ加わる',215)+table(['量','値'],[['全変位 (mm)',fmt(r.u)],['支持の変位 (mm)',fmt(r.support)],['固定支持からの変位増加 (%)',fmt(r.error*100)],['支持のエネルギー (N·mm)',fmt(50*r.support)]]);e.readout.innerHTML='<strong>硬い支持は「剛体拘束と完全に同じ」ではありません。</strong>この1方向の直列例ではks/kb=100で変位差1%。他のモデルにも一律に適用できる基準ではなく、極端な剛性比は数値条件を悪化させます。';}},
  autospc:{html:()=>frame(ui.slider('angle','強い主方向と成分1の角度（°）',0,90,5,45)+ui.slider('log','弱い剛性／強い剛性の10の指数',-12,-2,1,-9),'平面内の2×2局所剛性の説明用例。実際のGPSPは節点ごとに並進・回転の3×3ブロックを扱います。青の実線は強い主方向、破線は弱い主方向。実際の自動拘束の成分選択処理は再現していません。'),draw(e,v){out(e,v);const a=+v.angle*Math.PI/180,r=core.weak(+v.angle,+v.log),o=[180,105],P=(n,s)=>[o[0]+s*n[0],o[1]-s*n[1]];e.plot.innerHTML=svg(arrow([45,170],[315,170],'el-axis')+text(327,175,'1')+arrow([45,170],[45,35],'el-axis')+text(45,23,'2')+line(P([Math.cos(a),Math.sin(a)],-80),P([Math.cos(a),Math.sin(a)],80),'b3-edge')+line(P(r.n,-80),P(r.n,80),'el-ghost')+node(...o)+text(180,213,'λweak / λmax = '+(10**(+v.log)).toExponential(0)),'座標成分と剛性の主方向は異なる',235)+table(['剛性 (N/mm)','成分1','成分2'],[['成分1',...r.K[0].map(x=>fmt(x))],['成分2',...r.K[1].map(x=>fmt(x))]]);e.readout.innerHTML=`比は<strong>${r.ratio.toExponential(0)}</strong>。EPS=10⁻⁸との単純比較では${r.ratio<1e-8?'しきい値より小さい':'しきい値以上'}状態です。45°では対角のK11・K22が大きく見えても、ほぼ剛性のない斜め方向が存在します。しきい値を変える前に、その方向が物理的に必要か調べます。`; }},
  reactions:{html:()=>frame(ui.slider('a','荷重位置 a（mm）',40,360,20,120)+ui.select('basis','照合するモーメントの中心',[['A','左端A'],['B','右端B']],'A'),'長さ400 mmのピン・ローラー梁に下向き120 N。上向き力と反時計回りモーメントを正。反力矢印は値に比例し、力とモーメントを同じ座標系・同じ基準点へそろえて検算します。'),draw(e,v){out(e,v);const a=+v.a,r=core.reactions(a),loadX=55+250*a/400,origin=v.basis==='A'?0:400,mA=(0-origin)*r.RA,mB=(400-origin)*r.RB,mP=(a-origin)*(-120);e.plot.innerHTML=svg(line([55,100],[305,100])+roller(55,100,true)+roller(305,100)+arrow([loadX,35],[loadX,90])+text(loadX,22,'P = 120 N')+arrow([55,175],[55,175-r.RA*.5],'el-motion')+arrow([305,175],[305,175-r.RB*.5],'el-motion')+text(55,197,'RA')+text(305,197,'RB')+text(180,220,'a = '+a+' mm'),'荷重の位置と左右の支持反力',240)+table(['項','力 Fy (N)','選んだ中心まわり Mz (N·mm)'],[['A',fmt(r.RA),fmt(mA)],['B',fmt(r.RB),fmt(mB)],['P','−120',fmt(mP)],['合計',fmt(r.RA+r.RB-120),fmt(mA+mB+mP)]]);e.readout.innerHTML='<strong>合力が合っても、作用点が違えばモーメントは合いません。</strong>反力を支点ごとにまとめ、同一の基準点でr×Fも加えます。物体に作用する反力と、物体が支持へ及ぼす力は逆符号です。';}}
 };
 function connect(root){for(const e of root.querySelectorAll('[data-boundary-lab]'))ui.mount(e,labs[e.dataset.boundaryLab]);}
 window.BoundaryLabs={core,labs,connect,symmetryFigure,interfaceFigure,overhangFigure};
})();
